def frameRateMatching(input_video_folder, output_video_folder=None, target_frame_rate=12):
    if output_video_folder is None:
        output_folder_name = os.path.basename(input_video_folder) + f"_{target_frame_rate}FPS"
        output_video_folder = os.path.join(os.path.dirname(input_video_folder), output_folder_name)
    os.makedirs(output_video_folder, exist_ok=True)

    for video_file in os.listdir(input_video_folder):
        video_path = os.path.join(input_video_folder, video_file)

        if not os.path.isfile(video_path):
            continue

        # Open the input video file
        video_capture = cv2.VideoCapture(video_path)

        # Check if the video capture is successful
        if not video_capture.isOpened():
            print(f"Failed to open input video: {video_path}")
            continue

        # Get the current video's frame rate
        current_frame_rate = video_capture.get(cv2.CAP_PROP_FPS)
        print("Current Frame Rate:", current_frame_rate)

        # Assert that the target frame rate is smaller than the current frame rate
        assert target_frame_rate < current_frame_rate, "Target frame rate should be smaller than the current frame rate."

        # Compute the frame rate ratio
        frame_rate_ratio = current_frame_rate / target_frame_rate
        print("Frame Rate Ratio:", frame_rate_ratio)

        # Get the video's width and height
        width = int(video_capture.get(cv2.CAP_PROP_FRAME_WIDTH))
        height = int(video_capture.get(cv2.CAP_PROP_FRAME_HEIGHT))
        print("Resolution:", width, "x", height)

        # Set the output video path
        output_file_name = f"{os.path.splitext(video_file)[0]}.mp4"
        output_video_path = os.path.join(output_video_folder, output_file_name)
        print("Output Video Path:", output_video_path)

        # Create a VideoWriter object to save the output video
        fourcc = cv2.VideoWriter_fourcc(*'mp4v')  # Choose the desired output video codec
        output_video = cv2.VideoWriter(output_video_path, fourcc, target_frame_rate, (width, height))

        frame_count = 0

        while video_capture.isOpened():
            ret, frame = video_capture.read()

            # Break the loop if the video file is finished
            if not ret:
                break

            # Write out every nth frame, where n is the original fps divided by the target fps
            if frame_count % int(current_frame_rate / target_frame_rate) == 0:
                output_video.write(frame)

            frame_count += 1

        # Release the VideoCapture and VideoWriter objects
        video_capture.release()
        output_video.release()
        print(f"Output video saved successfully for: {video_path}")

def frameDiscretization(input_folder_path, step=30):
    output_folder_path = os.path.join(os.path.dirname(input_folder_path), "frames")

    for videoFile in os.listdir(input_folder_path):
        videoPath = os.path.join(input_folder_path, videoFile)

        if not os.path.isfile(videoPath):
            continue

        cap = cv2.VideoCapture(videoPath)
        if not cap.isOpened():
            print(f"Error opening video stream or file: {videoPath}")
            continue

        total = 0
        j = 1000000
        savePath = os.path.join(output_folder_path, f"{os.path.splitext(videoFile)[0]}")
        os.makedirs(savePath, exist_ok=True)

        print("Discretization Started!")
        while cap.isOpened():
            ret, frame = cap.read()
            if ret:
                if total + 1000000 == j:
                    cv2.imwrite(os.path.join(savePath, f'frame{j}.png'), frame)
                    j += int(step)
                total += 1
            else:
                break

        cap.release()
        cv2.destroyAllWindows()
        print(f"Discretization Ended for video: {videoPath}")

def resizeImages(folder_path, target_size=None):
    # If target_size is not provided, find the smallest dimension
    if target_size is None:
        smallest_dimension = float('inf')
        for root, dirs, files in os.walk(folder_path):
            for file in files:
                file_path = os.path.join(root, file)
                if file_path.endswith(('.jpg', '.jpeg', '.png', '.gif')):
                    image = cv2.imread(file_path)
                    height, width, _ = image.shape
                    smallest_dimension = min(smallest_dimension, height, width)

        print(f"The smallest image dimension is: {smallest_dimension}")
    else:
        assert isinstance(target_size, tuple) and len(target_size) == 2, \
            'target_size should be a tuple (width, height)'

    # Resize all images to the target size
    for root, dirs, files in os.walk(folder_path):
        for file in files:
            file_path = os.path.join(root, file)
            if file_path.endswith(('.jpg', '.jpeg', '.png', '.gif')):
                image = cv2.imread(file_path)
                height, width = image.shape[:2]

                # If target_size is provided, use it. Otherwise, calculate new size preserving aspect ratio.
                if target_size is not None:
                    new_size = target_size
                else:
                    aspect_ratio = float(width) / height  # Aspect Ratio = Width / Height
                    if width < height:
                        new_size = (smallest_dimension, int(smallest_dimension / aspect_ratio))
                    else:
                        new_size = (int(smallest_dimension * aspect_ratio), smallest_dimension)

                # Resize the image
                resized_image = cv2.resize(image, new_size)
                # Overwrite the original image
                cv2.imwrite(file_path, resized_image)

    print("Image resizing completed.")

def monocularCalibration(directory_path, chessboard_size=(7, 10), square_size=0.05):

    calibration_results = {}  # dictionary to store calibration results
    subdirectories = sorted(os.listdir(directory_path))

    # criteria used by checkerboard pattern detector.
    criteria = (cv2.TERM_CRITERIA_EPS + cv2.TERM_CRITERIA_MAX_ITER, 30, 0.001)

    rows = chessboard_size[0]  # number of checkerboard rows.
    columns = chessboard_size[1]  # number of checkerboard columns.
    world_scaling = square_size  # change this to the real world square size. Or not.

    # coordinates of squares in the checkerboard world space
    objp = np.zeros((rows * columns, 3), np.float32)
    objp[:, :2] = np.mgrid[0:rows, 0:columns].T.reshape(-1, 2)
    objp = world_scaling * objp

    for subdirectory in subdirectories:
        subdirectory_path = os.path.join(directory_path, subdirectory)
        images_names = sorted(glob.glob(os.path.join(subdirectory_path, '*.png')))

        if not images_names:  # Skip if no images in subdirectory
            continue

        images = []
        for imname in images_names:
            im = cv2.imread(imname, 1)
            images.append(im)

        # frame dimensions. Frames should be the same size.
        width = images[0].shape[1]
        height = images[0].shape[0]
        # Pixel coordinates of checkerboards
        imgpoints = []  # 2d points in image plane.
        # coordinates of the checkerboard in checkerboard world space.
        objpoints = []  # 3d point in real world space

        used_images = []  # List of images used for calibration
        discarded_images = []  # List of images discarded

        for imname, frame in zip(images_names, images):
            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            # find the checkerboard
            ret, corners = cv2.findChessboardCorners(gray, (rows, columns), None)
            if ret == True and len(corners) == rows * columns:
                # Convolution size used to improve corner detection. Don't make this too large.
                conv_size = (11, 11)
                # opencv can attempt to improve the checkerboard coordinates
                corners = cv2.cornerSubPix(gray, corners, conv_size, (-1, -1), criteria)
                cv2.drawChessboardCorners(frame, (rows, columns), corners, ret)

                print("Press y/n if the image is okay.")
                cv2.imshow(imname, frame)  # Use the image name as the title

                while True:
                    k = cv2.waitKey(0)
                    if k == ord('y'):
                        objpoints.append(objp)
                        imgpoints.append(corners)
                        used_images.append(imname)
                        cv2.destroyWindow(imname)  # Close the window immediately after 'y' key press
                        break
                    elif k == ord('n'):
                        discarded_images.append(imname)
                        # Delete the image from the directory
                        try:
                            os.remove(imname)
                            print("Image deleted.")
                        except FileNotFoundError:
                            print("Image not found.")
                        except Exception as e:
                            print(f"Error while trying to delete the image: {e}")
                        cv2.destroyWindow(imname)  # Close the window immediately after 'n' key press
                        break
            else:
                discarded_images.append(imname)
                # Delete the image from the directory
                try:
                    os.remove(imname)
                    print("Image deleted.")
                except FileNotFoundError:
                    print("Image not found.")
                except Exception as e:
                    print(f"Error while trying to delete the image: {e}")

        ret, mtx, dist, rvecs, tvecs = cv2.calibrateCamera(objpoints, imgpoints, (width, height), None, None)

        # Save the results into the dictionary
        calibration_results[subdirectory] = {"mtx": mtx, "dist": dist}

        # Print images used and discarded
        print(f"Images used for calibration in {subdirectory}: {len(used_images)}")
        print("\n".join(used_images))
        print(f"Images discarded in {subdirectory}: {len(discarded_images)}")
        print("\n".join(discarded_images))

    cv2.destroyAllWindows()  # Close all OpenCV windows at the end

    return calibration_results

    cv2.destroyAllWindows()  # Close all OpenCV windows at the end

    return calibration_results

def matchedImageStorage(directory_path1, directory_path2, chessboard_size=(7, 10), square_size=0.05):
    # Extract original folder names
    original_folder_name1 = os.path.basename(directory_path1)
    original_folder_name2 = os.path.basename(directory_path2)

    # Create a directory for matched frames in the parent directory
    parent_dir = os.path.dirname(directory_path1)
    grandparent_dir = os.path.dirname(parent_dir)
    matched_frames_dir = os.path.join(grandparent_dir, 'MatchedFrames')
    os.makedirs(matched_frames_dir, exist_ok=True)

    # Create subdirectory in MatchedFrames for the current pair of directories
    matched_pair_dir = os.path.join(matched_frames_dir, f"{original_folder_name1}-{original_folder_name2}")
    os.makedirs(matched_pair_dir, exist_ok=True)

    # Criteria for corner subpixel accuracy
    criteria = (cv2.TERM_CRITERIA_EPS + cv2.TERM_CRITERIA_MAX_ITER, 30, 0.001)

    files1 = [name for name in os.listdir(directory_path1) if os.path.isfile(os.path.join(directory_path1, name))]
    files2 = [name for name in os.listdir(directory_path2) if os.path.isfile(os.path.join(directory_path2, name))]

    # Intersect files in both directories
    common_files = list(set(files1) & set(files2))

    # Sort common files alphabetically
    sorted_files = sorted(common_files)

    # Initialize counter for detected checkerboards
    checkerboard_detected_count = 0

    for file in sorted_files:
        image_path1 = os.path.join(directory_path1, file)
        image_path2 = os.path.join(directory_path2, file)

        image1 = cv2.imread(image_path1)
        image2 = cv2.imread(image_path2)

        if image1 is None or image2 is None:
            print(f"Error loading images: {image_path1}, {image_path2}")
            continue

        gray1 = cv2.cvtColor(image1, cv2.COLOR_BGR2GRAY)
        gray2 = cv2.cvtColor(image2, cv2.COLOR_BGR2GRAY)

        ret1, corners1 = cv2.findChessboardCorners(gray1, chessboard_size, None)
        ret2, corners2 = cv2.findChessboardCorners(gray2, chessboard_size, None)

        if ret1 and ret2 and len(corners1) == len(corners2) == (chessboard_size[0] * chessboard_size[1]):
            # Draw corners on images
            image1_copy = image1.copy()
            image2_copy = image2.copy()

            draw_img1 = cv2.drawChessboardCorners(image1_copy, chessboard_size, corners1, ret1)
            draw_img2 = cv2.drawChessboardCorners(image2_copy, chessboard_size, corners2, ret2)

            draw_img1_resized = cv2.resize(draw_img1, (960,540))
            draw_img2_resized = cv2.resize(draw_img2, (960,540))

            # Display images to user
            cv2.imshow('Image 1', draw_img1_resized)
            cv2.imshow('Image 2', draw_img2_resized)

            print("Press 's' to save the image for calibration or any other key to discard.")
            # Wait for user input: 's' for save, any other key to discard
            key = cv2.waitKey(0) & 0xFF
            if key == ord('s'):
                # Save the images in the matched frames folder
                matched_dir1 = os.path.join(matched_pair_dir, original_folder_name1)
                matched_dir2 = os.path.join(matched_pair_dir, original_folder_name2)

                os.makedirs(matched_dir1, exist_ok=True)
                os.makedirs(matched_dir2, exist_ok=True)

                cv2.imwrite(os.path.join(matched_dir1, file), image1)
                cv2.imwrite(os.path.join(matched_dir2, file), image2)

                # Increment counter
                checkerboard_detected_count += 1
            else:
                print(f"Images discarded by user: {image_path1}, {image_path2}")

            # Destroy the windows to avoid GUI issues
            cv2.destroyAllWindows()

        else:
            print(
                f"No or incorrect number of corners detected for images: {image_path1}, {image_path2}. Skipping...")

    # Print the number of images where the checkerboard was detected
    print(
        f"Number of images with detected checkerboard in {original_folder_name1}_{original_folder_name2}: {checkerboard_detected_count}")

def matchedImageStorage_for_all_cameras_views(directory_path, chessboard_size=(7, 10)):
    parent_dir = os.path.dirname(directory_path)
    matched_frames_dir = os.path.join(parent_dir, 'MatchedFrames-AllViews')
    os.makedirs(matched_frames_dir, exist_ok=True)

    # Intersect files in all subdirectories
    common_files = set()
    subdirs = [subdir for subdir in os.listdir(directory_path) if os.path.isdir(os.path.join(directory_path, subdir))]
    for subdir in subdirs:
        subdir_path = os.path.join(directory_path, subdir)
        files = set(os.listdir(subdir_path))
        if not common_files:
            common_files = files
        else:
            common_files &= files

    # Sort common files alphabetically
    sorted_files = sorted(common_files)

    # Initialize counter for detected checkerboards
    checkerboard_detected_count = 0

    for file in sorted_files:
        image_paths = [os.path.join(directory_path, subdir, file) for subdir in subdirs]
        images = [cv2.imread(image_path) for image_path in image_paths]

        all_images_loaded = all(image is not None for image in images)
        if not all_images_loaded:
            print(f"Error loading images: {', '.join(image_paths)}")
            continue

        gray_images = [cv2.cvtColor(image, cv2.COLOR_BGR2GRAY) for image in images]

        ret_list, corners_list = [], []
        for gray_img in gray_images:
            ret, corners = cv2.findChessboardCorners(gray_img, chessboard_size, None)
            if ret:
                ret_list.append(ret)
                corners_list.append(corners)
            else:
                ret_list.append(False)
                corners_list.append(None)

        if all(ret_list) and all(len(corners) == (chessboard_size[0] * chessboard_size[1]) for corners in corners_list):
            # Draw corners on images and display to the user
            images_copy = [image.copy() for image in images]
            draw_images = [cv2.drawChessboardCorners(image_copy, chessboard_size, corners, True)
                           for image_copy, corners in zip(images_copy, corners_list)]

            for i, draw_img in enumerate(draw_images):
                draw_img_resized = cv2.resize(draw_img, (960, 540))
                cv2.imshow(f'Image from camera {i + 1}', draw_img_resized)

            print("Press 's' to save the image for calibration or any other key to discard.")
            # Wait for user input: 's' for save, any other key to discard
            key = cv2.waitKey(0) & 0xFF
            if key == ord('s'):
                # Save the images in the matched frames folder
                matched_subdirs = [os.path.join(matched_frames_dir, subdir) for subdir in subdirs]
                for image, matched_subdir in zip(images, matched_subdirs):
                    os.makedirs(matched_subdir, exist_ok=True)
                    cv2.imwrite(os.path.join(matched_subdir, file), image)

                # Increment counter
                checkerboard_detected_count += 1
            else:
                print(f"Images discarded by user: {', '.join(image_paths)}")

            # Destroy the window to avoid GUI issues
            cv2.destroyAllWindows()

        else:
            print(f"No or incorrect number of corners detected for images: {', '.join(image_paths)}. Skipping...")

    # Print the number of images where the checkerboard was detected
    print(f"Number of images with detected checkerboard in common between all cameras: {checkerboard_detected_count}")

def stereoCalibration(calibration_results, parent_folder, chessboard_size=(7, 10), square_size=0.05):
    # Extract subfolder names
    subfolder_names = os.listdir(parent_folder)
    if len(subfolder_names) != 2:
        raise Exception("Parent folder should contain exactly 2 subfolders")

    # Load calibration results
    with open(calibration_results, 'rb') as f:
        calibration_data = pickle.load(f)

    # for key, value in calibration_data.items():
    #     print(f"{key}: {value}")

    # Get the mtx and dist for the two folders
    mtx1, dist1 = calibration_data[subfolder_names[0]]["mtx"], calibration_data[subfolder_names[0]]["dist"]
    mtx2, dist2 = calibration_data[subfolder_names[1]]["mtx"], calibration_data[subfolder_names[1]]["dist"]

    image_folder1 = os.path.join(parent_folder, subfolder_names[0])
    image_folder2 = os.path.join(parent_folder, subfolder_names[1])

    c1_images_names = glob.glob(os.path.join(image_folder1, '*.png'))
    c1_images_names = sorted(c1_images_names)

    c2_images_names = glob.glob(os.path.join(image_folder2, '*.png'))
    c2_images_names = sorted(c2_images_names)

    c1_images = []
    c2_images = []

    for im1, im2 in zip(c1_images_names, c2_images_names):
        _im = cv2.imread(im1, 1)
        c1_images.append(_im)
        _im = cv2.imread(im2, 1)
        c2_images.append(_im)

        criteria = (cv2.TERM_CRITERIA_EPS + cv2.TERM_CRITERIA_MAX_ITER, 100, 0.0001)

        rows = chessboard_size[0]  # number of checkerboard rows.
        columns = chessboard_size[1]  # number of checkerboard columns.
        world_scaling = square_size  # change this to the real world square size. Or not.

        objp = np.zeros((rows * columns, 3), np.float32)
        objp[:, :2] = np.mgrid[0:rows, 0:columns].T.reshape(-1, 2)
        objp = world_scaling * objp

        width = c1_images[0].shape[1]
        height = c1_images[0].shape[0]

        imgpoints_left = []
        imgpoints_right = []
        objpoints = []

        for frame1, frame2 in zip(c1_images, c2_images):
            gray1 = cv2.cvtColor(frame1, cv2.COLOR_BGR2GRAY)
            gray2 = cv2.cvtColor(frame2, cv2.COLOR_BGR2GRAY)
            c_ret1, corners1 = cv2.findChessboardCorners(gray1, (rows, columns), None)
            c_ret2, corners2 = cv2.findChessboardCorners(gray2, (rows, columns), None)
            if c_ret1 == True and c_ret2 == True:
                corners1 = cv2.cornerSubPix(gray1, corners1, (11, 11), (-1, -1), criteria)
                corners2 = cv2.cornerSubPix(gray2, corners2, (11, 11), (-1, -1), criteria)
                cv2.drawChessboardCorners(frame1, (rows, columns), corners1, c_ret1)
                cv2.drawChessboardCorners(frame2, (rows, columns), corners2, c_ret2)
                objpoints.append(objp)
                imgpoints_left.append(corners1)
                imgpoints_right.append(corners2)

        stereocalibration_flags = cv2.CALIB_FIX_INTRINSIC
        ret, CM1, dist1, CM2, dist2, R, T, E, F = cv2.stereoCalibrate(objpoints, imgpoints_left, imgpoints_right,
                                                                      mtx1, dist1, mtx2, dist2, (width, height),
                                                                      criteria=criteria, flags=stereocalibration_flags)
        return R, T

def calculateProjectionMatrices(file_path_dict1, file_path_dict2, reference_camera, secondary_camera):
    # Load the dictionaries from the pkl files
    with open(file_path_dict1, "rb") as f1:
        dict1 = pickle.load(f1)

    with open(file_path_dict2, "rb") as f2:
        dict2 = pickle.load(f2)

    # Get the matrices and R, T for the reference camera
    mtx1 = dict1[reference_camera]['mtx']
    mtx2 = dict1[secondary_camera]['mtx']
    R, T = dict2[0], dict2[1]

    # Calculate the projection matrices
    RT1 = np.concatenate([np.eye(3), [[0], [0], [0]]], axis=-1)
    P1 = np.matmul(mtx1, RT1)

    RT2 = np.concatenate([R, T], axis=-1)
    P2 = np.matmul(mtx2, RT2)

    return P1, P2

def DLT(P1, P2, point1, point2):
    A = [point1[1] * P1[2, :] - P1[1, :],
         P1[0, :] - point1[0] * P1[2, :],
         point2[1] * P2[2, :] - P2[1, :],
         P2[0, :] - point2[0] * P2[2, :]
         ]
    A = np.array(A).reshape((4, 4))
    # print('A: ')
    # print(A)
    B = A.transpose() @ A
    from scipy import linalg
    U, s, Vh = linalg.svd(B, full_matrices=False)
    # print('Triangulated point: ')
    # print(Vh[3, 0:3] / Vh[3, 3])
    return Vh[3, 0:3] / Vh[3, 3]

def plot_triangulated_points(triangulated_points_list, batch_size, colors_list):
    fig = plt.figure(figsize=(6, 6))
    ax = fig.add_subplot(111, projection='3d')

    for points, color in zip(triangulated_points_list, colors_list):
        # Determine number of batches
        num_batches = np.ceil(len(points) / batch_size).astype(int)

        # Create a colormap
        cmap = plt.cm.get_cmap('rainbow', num_batches)

        # Loop over the batches
        for i in range(num_batches):
            # Get the points in this batch
            batch_points = points[i * batch_size:(i + 1) * batch_size]
            # Plot the points in this batch with the color specified by the colormap
            ax.scatter(batch_points[:, 0], batch_points[:, 2], batch_points[:, 1], marker='o', color=cmap(i))

    # Set the axis labels
    ax.set_xlabel('X')
    ax.set_ylabel('Y')
    ax.set_zlabel('Z')

    plt.title("3D Reconstructed CheckerBoard")
    plt.show()

