def make_homogeneous_matrix(R, T):
    # Ensure R is a 3x3 matrix and T is a 3x1 vector
    R = np.asarray(R)
    T = np.asarray(T)
    if R.shape != (3, 3):
        raise ValueError("Rotation matrix (R) must be a 3x3 matrix.")
    if T.shape != (3, 1):
        raise ValueError("Translation vector (T) must be a 3x1 vector.")

    RT = np.hstack([R, T])
    return np.vstack([RT, [0, 0, 0, 1]])

def triangulation(fileList):
    """
        This function calculates the positions and orientations of cameras in 3D space
        based on the given input data
    """
    # Get a list of all pickle files in the folder
    pickle_files = [f for f in fileList if f.endswith('.pkl')]

    # Sort the files to ensure correct order (e.g., Cam1-Cam2-RandT.pkl should come before Cam2-Cam3-RandT.pkl)
    pickle_files.sort()

    # Initialize the transformation matrix and rotation matrix of the first camera as identity
    world_to_cam_transforms = [np.eye(4)]
    world_to_cam_rotations = [np.eye(3)]

    # Initialize the list of translations with a zero vector
    translations = [[0, 0, 0]]
    # Loop through each pair of cameras and perform triangulation
    for file_path in pickle_files:
        # Load rotation and translation data from the pickle file
        with open(file_path, 'rb') as f:
            R, T = pickle.load(f)

        # Concatenate rotation and translation to form the 4x4 transformation matrix
        RT = make_homogeneous_matrix(R, T)

        # Get the transformation and rotation of the previous camera
        prev_cam_transform = world_to_cam_transforms[-1]

        # Compute the absolute transformation by multiplying with the inverse of the previous camera's transformation
        abs_transform = np.matmul(prev_cam_transform, np.linalg.inv(RT))
        world_to_cam_transforms.append(abs_transform)

        # Compute the absolute rotation by multiplying with the previous camera's rotation
        abs_rotation = np.matmul(R, world_to_cam_rotations[-1])
        world_to_cam_rotations.append(abs_rotation)

        # Compute the translation between the current and previous camera positions
        translation = abs_transform[:3, 3] - world_to_cam_transforms[-2][:3, 3]
        translations.append(translation)


    # Extract the absolute positions, translations, and rotations of all cameras
    absolute_positions = [world_to_cam_transforms[i][:3, 3] for i in range(len(world_to_cam_transforms))]
    rotations = world_to_cam_rotations

    # Convert the absolute_positions list to a 2D array with shape (3, num_cameras)
    absolute_positions_arr = np.column_stack(absolute_positions)

    return absolute_positions, translations, rotations

def plot_camera_positions_with_orientation(positions, rotations):
    fig = plt.figure()
    ax = fig.add_subplot(111, projection='3d')
    ax.set_xlabel('X')
    ax.set_ylabel('Y')
    ax.set_zlabel('Z')
    ax.set_title('Camera Positions and Orientations')

    # # Extract x, y, z coordinates of camera positions
    # x = [pos[0] for pos in positions]
    # y = [pos[1] for pos in positions]
    # z = [pos[2] for pos in positions]
    #
    # ax.scatter(x, y, z, c='red', marker='o', label='Camera Positions')
    #
    # # Plot the orientation of each camera as a blue ray
    # for i in range(len(positions)):
    #     direction_vector = rotations[i] @ np.array([0, 0, 1])  # Assuming camera points along the z-axis
    #     direction_vector = -1 * direction_vector  # Reverse the direction of the vector
    #     ax.quiver(positions[i][0], positions[i][1], positions[i][2],
    #               direction_vector[0], direction_vector[1], direction_vector[2],
    #               color='blue', length=0.5, label=f'Camera {i+1} Orientation')

    # Extract x, y, z coordinates of camera positions
    x = [pos[0] for pos in positions]
    y = [pos[2] for pos in positions]  # Swap y and z
    z = [pos[1] for pos in positions]  # Swap z and y

    ax.scatter(x, y, z, c='red', marker='o', label='Camera Positions')

    # Plot the orientation of each camera as a blue ray
    for i in range(len(positions)):
        # Adjust the direction vector based on the new order of x, y, and z
        direction_vector = rotations[i] @ np.array([1, 0, 0])  # Assuming camera points along the x-axis
        direction_vector = direction_vector * np.array([1, 0, -1])  # Adjust the direction vector
        ax.quiver(x[i], y[i], z[i],
                  direction_vector[0], direction_vector[2], direction_vector[1],  # Adjust the order of the components
                  color='blue', length=0.5, label=f'Camera {i + 1} Orientation')

    plt.legend()
    plt.show()

def create_projection_matrices(calibration_results, rotations, absolute_positions):
    projection_matrices = []
    for i in range(len(calibration_results)):
        # mtx = calibration_results[f'Cam{i+1}']['mtx'] # rename Cam to CB or whatever
        mtx = calibration_results[f'CB{i+1}']['mtx'] # rename Cam to CB or whatever
        R = np.array(rotations[i])
        T = np.array(absolute_positions[i])
        T = T.reshape(-1, 1)
        RT = np.hstack([R, T])
        projection_matrices.append(np.matmul(mtx, RT))

    return projection_matrices

def multi_view_triangulation(Ps, points):
    """
    Performs multi-view triangulation.
    Parameters:
        Ps: List of projection matrices for each camera.
        points: List of corresponding 2D points in each camera.
    Returns:
        X: 3D point that best fits the observations.
    """
    A = []
    for P, point in zip(Ps, points):
        A.append(point[1] * P[2, :] - P[1, :])
        A.append(P[0, :] - point[0] * P[2, :])

    A = np.array(A)
    # print(A.shape)
    B = A.transpose() @ A
    # print(B.shape)

    from scipy import linalg
    U, s, Vh = linalg.svd(B, full_matrices=False)
    # print(Vh[3, 0:3] / Vh[3, 3])
    return Vh[3, 0:3] / Vh[3, 3]

